void abort(void);
void exit(int);

typedef unsigned long long uint64;
const uint64               bigconst = 1ULL << 34;

int a = 1;

static uint64 getmask(void) {
  if (a)
    return bigconst;
  else
    return 0;
}

int main(void) {
  uint64 f = getmask();
  if (sizeof(long long) == 8 && f != bigconst)
    abort();
  exit(0);
}


